{
  "subtype": "faceted_decomposition",
  "concept": "audience_praise_and_complaints",
  "per_column": [
    {
      "name": "praised_aspect",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The praise dimension is one of the two constitutive halves of 'praise and complaints', and this column decomposes it by the film aspect being praised (acting, cinematography, screenplay, etc.), which is an aspect OF the praise concept rather than an external predictor or cause."
    },
    {
      "name": "complaint_aspect",
      "is_constitutive_facet": true,
      "role": "facet",
      "rationale": "The complaint dimension is the other constitutive half of the concept, decomposed by the film aspect being criticized. This is genuinely a part-of the focus concept."
    }
  ],
  "facet_columns": ["praised_aspect", "complaint_aspect"],
  "non_facet_columns": [],
  "mutual_exclusivity": 0.9,
  "exhaustiveness": 0.85,
  "rationale": "Both columns are constitutive facets: the concept 'praise and complaints' is explicitly a two-part valenced construct, and the columns cleanly partition it into the praise facet and the complaint facet, each further specifying WHICH aspect of the film is being evaluated. Mutual exclusivity is high because praise vs. complaint are non-overlapping by valence and are stored as separate columns; the only minor overlap is that both share the same underlying aspect vocabulary (e.g., 'acting', 'screenplay', 'cinematography'), but since they are conditioned on opposite valence they do not double-count. Exhaustiveness is strong for the top-level valence decomposition (praise + complaint covers the whole concept), though the aspect-level enumeration is not exhaustive of all evaluative dimensions and relies on a 'not_present' catch-all, slightly reducing coverage of the concept's full constitutive space."
}

